dtsPropsFor.AppShell:
/** Signed-in user; role "admin" unlocks the Basic/Advanced view switch. */
  session: { id: string; name: string; email: string; title: string; team: string; status: string; avatar: string; role: "admin" | "user"; accessToken?: string; sessionType: "demo" | "oidc"; /** First sign-in: Home greets instead of welcoming back. */ firstVisit?: boolean; /** When they last signed in before this one. */ previousSignIn?: string };
  /** The operator's stored Basic/Advanced choice, read from its cookie by the server. */
  initialView?: "basic" | "advanced";
  children: React.ReactNode;

dtsPropsFor.ActionOutcome:
outcome: { kind: "applied" | "queued" | "no_change" | "refused" | "failed"; /** What happened, in physical terms. */ message: string; detail?: string; /** Present on refused and failed. */ requestId?: string; sessionEnded?: boolean; /** Syndra sends it on its own (no Send needed). */ sendsItself?: boolean; /** Some of it happened: what did not. */ partial?: string; /** The caller's own next step; otherwise the kind decides. */ next?: string; recorded?: boolean; /** Seconds before trying again is useful. */ retryAfter?: number };
  placement?: "inline" | "block" | "seat";
  /** The decision in the act's own vocabulary ("Approved", "Given", "Given to 12 people"). Required: never a generic "Applied". */
  word: string;
  /** The person this change is about: "Waiting for you to send" opens Pending changes narrowed to them. */
  person?: string;
  className?: string;

dtsPropsFor.PlanReview:
plan: { op: "assign_role" | "remove_role" | "assign_bundle" | "remove_bundle" | "extend" | "create_mapping" | "edit_mapping" | "delete_mapping" | "rollback_mappings" | "publish_bundle_version" | "move_bundle_holders"; /** Present on a rehearsal (the approval an apply must cite). */ plan_id?: string; applied: boolean; outcomes: Array<{ user_id: string; name: string; email: string; effect: "apply" | "applied" | "no_change" | "blocked" | "failed" | "queued"; detail: string; consequence?: string; grant_ids?: string[]; /** Why it waits, in words. */ wait_reason?: string; sends_on_its_own?: boolean; retry?: { state: "retrying" | "waiting"; try: number; of: number; next_try?: string }; rule_waiting?: number; delivery?: "straight_away" | "waits_for_you" | "none"; /** The roles that wait, and the roles that go now. */ waits?: string[]; goes?: string[]; unsent?: number; person?: string }>; /** People left out of the plan (the operator themself). */ excluded?: Array<{ user_id: string; reason: "self" }>; summary: { total: number; apply: number; no_change: number; blocked: number; failed: number; succeeded: number; queued: number } };
  /** What the plan rows are, singular/plural, e.g. ["account", "accounts"]. */
  noun?: [string, string];
  /** Whether this server sends changes again on its own (null: not known yet): which fold a queued row sits in after Apply. */
  auto?: boolean | null;
  /** The system the change is sent to, for the words. */
  system?: string;

dtsPropsFor.ReadFreshness:
state: { /** When the target was read; absent = never. */ readAt?: string | null; /** false = from the add-on mirror (provisional at any age). */ current?: boolean; /** The read hit the add-on cap. */ truncated?: boolean };
  subject?: string;
  /** Who is reading: it words the step beside a system that cannot be reached. */
  reader?: { audience: "member" } | { audience: "operator"; person: string };
  onRefresh?: () => unknown;
  refreshing?: boolean;
  /** When the press is somewhere else on the page (a header button), its useRefreshPress(). */
  refresh?: { pressing: boolean; landed: string | null; press: (run: () => unknown) => Promise<void> };
  className?: string;

dtsPropsFor.Withheld:
items: Array<{ /** Entitlement field it applies to, e.g. "group", "share". */ field: string; /** The value withheld, as the member would recognise it. */ value: string; reason: string; /** Which system it is on. */ target?: string; /** Who decided it. */ actorId?: string; /** Past the promised review date. */ reviewDue?: boolean }>;
  audience?: "member" | "operator";
  /** Each system's fields, from the response the page loaded. */
  schemaOf?: ((system: string | undefined) => Array<{ name: string; role: "account" | "channel" | "membership" | "flag" | "limit"; label?: string; unit?: string; combine?: string; unlimited?: string; per_person?: boolean }> | undefined) & { loading?: boolean; error?: unknown; refetch?: () => void; nameOf?: (system: string) => string };
  className?: string;

dtsPropsFor.Segmented:
/** Generic over the option value type in source; string here. */
  /** `title` is the segment's own hover text, for a choice that needs a sentence beside its word. */
  options: { value: string; label: string; title?: string; disabled?: boolean }[];
  value: string;
  onChange: (next: string) => void;
  size?: "sm" | "md";
  label: string;
  /** The id of a sentence that explains the whole choice. */
  describedBy?: string;
  /** Spans its container, each segment an equal share: the phone sheet's form. */
  fill?: boolean;

dtsPropsFor.FilterPills:
/** Generic over the option value type in source; string here. */
  options: { value: string; label: string; }[];
  value: string;
  onChange: (next: string) => void;
  label: string;

dtsPropsFor.Tabs:
/** Generic over the option value type in source; string here. */
  options: { value: string; label: React.ReactNode; }[];
  value: string;
  onSelect: (next: string) => void;
  /** Names the group for a screen reader — "Views of this person's access". */
  label: string;
  className?: string;

dtsPropsFor.SortHead:
label: string;
  /** Generic over the sort key type in source; string here. */
  name: string;
  /** From `useSort`: the heading in force and its direction. */
  sort: { key: string; dir: 1 | -1 };
  onSort: (key: string) => void;
  /** What a screen reader hears after "Sort by"; the label, lower-cased, by default. */
  by?: string;

dtsPropsFor.ReadLine:
/** Generic over NavSection in source; NavSection here. */
  sections: Array<{ /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }>;
  onOpen?: (section: { /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }) => void;
  /** Names the chips for a screen reader: "Sections of drift". */
  label: string;
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.SectionPill:
/** Generic over NavSection in source; NavSection here. */
  sections: Array<{ /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }>;
  onOpen?: (section: { /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }) => void;
  label: string;
  gap?: number;

dtsPropsFor.PushedStep:
/** The return of `useCancelStep({ host, goAhead, tone?, standalone? })`; `step.run(write)` or `step.confirm(changes, write)` pushes the step when the write is refused with WouldCancelQueued. */
  step: { /** A write not on the planner: on its 409, the step, then write(the ids shown). */ run: <T>(write: (cancelIds?: string[]) => Promise<T>) => Promise<T | symbol>; /** The press of an act the planner planned: the step is pushed at once with the plan's changes. */ confirm: <T>(changes: Array<{ id: string; op_type: string; user_id: string; project_id: string; role_keys: string[]; source: string; initiated_by: string; initiated_by_name?: string; said?: string; queued_at: string; new?: boolean }>, write: () => Promise<T>) => Promise<T | symbol>; /** The step is on screen (or fading back to the form). */ asking: { changes: Array<{ id: string; op_type: string; user_id: string; project_id: string; role_keys: string[]; source: string; initiated_by: string; initiated_by_name?: string; said?: string; queued_at: string; new?: boolean }>; fresh: Set<string>; busy: boolean; closed: boolean; answer: (goAhead: boolean) => void } | null; open: boolean; note: React.ReactNode; after: React.ReactNode; element: React.ReactNode; view: React.ReactNode };
  children: React.ReactNode;

dtsPropsFor.GlideIndicator:
/** From `useGlideIndicator(choice)`: the active button's box, null until measured. */
  box: { left: number; top: number; width: number; height: number } | null;
  kind: "fill" | "underline";
  /** The indicator's colour, a token class. */
  className?: string;

dtsPropsFor.GoTo:
open: boolean;
  onClose: () => void;
  /** Which pages may be listed: the current view's nav tree (NavEntry[] in source: a leaf, or a group of leaves). */
  nav: Array<{ kind: "leaf"; label: string; href: string } | { kind: "group"; label: string; children: Array<{ kind: "leaf"; label: string; href: string }> }>;

dtsPropsFor.StandingLine:
standing: { usable: boolean; waiting_on: "member" | "operator" | "target" | "none"; /** The add-on's own note. */ note?: string; /** The add-on's own next step. */ next?: string };
  /** The system's name, as the reader knows it. */
  system: string;
  audience: "member" | "operator";
  /** false: the state and its note only, for a narrow status column. */
  step?: boolean;

dtsPropsFor.GoToPanel:
nav: Array<{ kind: "leaf"; label: string; href: string } | { kind: "group"; label: string; children: Array<{ kind: "leaf"; label: string; href: string }> }>;
  /** Called when a row is opened, so the host can close. */
  onGo: () => void;
  /** Inside the phone's Go to sheet: no key hints, rows replace. */
  embedded?: boolean;
  /** Embedded only: what the sheet shows while the Input is empty. */
  idle?: React.ReactNode;
